message.content:
{
  "issues": [
    "完整档字段格式不符：fears 应为数组，草稿中为字符串。"
  ],
  "profile": {
    "personality": {
      "traits": [
        "细致耐心",
        "务实寡言",
        "护家心重"
      ],
      "values": [
        "把活干得不出错",
        "家人平安"
      ],
      "flaws": "遇事容易先往坏处想"
    },
    "voice": {
      "register": "日常口语，夹杂货栈行话",
      "accent": "河岸一带的平缓口音",
      "habits": [
        "说话前先停一下",
        "核对数目时会低声念出来"
      ],
      "samples": [
        "这批货的单子我再对一遍，少一张都走不了。",
        "车什么时候到？我这边交接得赶在落雨前。",
        "海儿，别在货堆边上跑。"
      ]
    },
    "background": "从小在站西长大，河岸货栈的活计做了大半辈子。年轻时帮着抄货单，后来接车、点货、对账，一样样学下来。成家后仍旧守着这片货栈，日子跟着船期走，忙时脚不沾地，闲时补觉。伴侣也在附近讨生活，孩子还小，她把家里和货栈两头都攥得紧。",
    "currentConcern": "雨季前货栈进出量大，怕交接出错，也怕孩子独自在家没人看。",
    "goals": [
      "把这一季的货单交接做得清清楚楚，不出岔子",
      "攒够力气让家里日子稳当些"
    ],
    "fears": [
      "怕货单对不上，连累同栈的人受罚。"
    ],
    "knowledge": {
      "unknown": [
        "货栈账目背后是谁在调度",
        "河上游为何近来船期总变"
      ]
    },
    "relationships": [
      {
        "with": "npc_pop_bs_003_2",
        "relation": "子女",
        "note": "孩子还小，她出门上工前总要托邻居多看两眼，收工回来第一件事就是找孩子。"
      },
      {
        "with": "npc_pop_bs_003_3",
        "relation": "伴侣",
        "note": "两人各忙各的活计，夜里凑在一起对第二天的安排，话不多但彼此搭手。"
      }
    ],
    "visibleFeature": "常年搬点货物磨出的厚茧手，袖口总别着一截用来记数的炭条。"
  }
}
